/* From Uiverse.io by Pradeepsaranbishnoi - Tags: loader, retro, windows, xp */
.__UIV_SCOPE__ .container {
  width: 150px;
  height: 10px;
  border: 2px solid #b2b2b2;
  border-radius: 7px;
  margin: 0 auto;
  padding: 2px 1px;
  overflow: hidden;
  font-size: 0;
}

.__UIV_SCOPE__ .box {
  width: 9px;
  height: 100%;
  background: linear-gradient(to bottom, #2838c7 0%,#5979ef 17%,#869ef3 32%,#869ef3 45%,#5979ef 59%,#2838c7 100%);
  display: inline-block;
  margin-right: 2px;
  animation: loader 2s infinite;
  animation-timing-function: linear;
}

.__UIV_SCOPE__ .logo {
  width: 220px;
  margin: 50px auto;
  margin-top: 20px;
}

.__UIV_SCOPE__ .logo p {
  margin: 0;
  padding: 0;
}

.__UIV_SCOPE__ .top {
  font-size: 16px;
  font-weight: 300;
  line-height: 16px;
}

.__UIV_SCOPE__ .top:after {
  content: "\00a9";
  font-size: 10px;
  position: relative;
  top: -5px;
  margin-left: 2px;
}

.__UIV_SCOPE__ .mid {
  font-size: 46px;
  font-weight: 700;
  line-height: 36px;
}

.__UIV_SCOPE__ .mid span {
  font-size: 22px;
  display: inline-block;
  vertical-align: top;
  color: #FF6821;
  margin-top: -8px;
}

.__UIV_SCOPE__ .logo .bottom {
  font-size: 30px;
  font-weight: 300;
  line-height: 30px;
  margin-left: 5px;
}

@keyframes loader {
  0% {
    transform: translate(-30px);
  }

  100% {
    transform: translate(150px);
  }
}
